function getScenario(){return scenarioVariants[(Number(state.scenarioId)||0)%scenarioVariants.length]}
function renderInstructorConsole(){document.getElementById("instructorGate").style.display="none";document.getElementById("instructorConsole").style.display="block";document.getElementById("scenarioCards").innerHTML=scenarioVariants.map((v,i)=>'<article class="scenario-card"><div class="case-id">CASE FILE · NX-'+String(i+1).padStart(2,"0")+'</div><h3>Escenario '+String(i+1).padStart(2,"0")+' · '+esc(v.label)+'</h3><p><span class="scenario-chip">DEMANDA '+v.demand+' BOMBAS</span> <span class="scenario-chip">FECHA '+v.required+'</span></p><ul><li>Proveedor habitual: '+esc(v.supplier)+' · '+v.normalDays+' días.</li><li>Alternativa: '+esc(v.altSupplier)+' · '+v.altDays+' días · +'+v.altPremium+'%.</li><li>Rodamientos: necesidad '+v.bearingNeed+'; físico '+v.bearingPhysical+', reservado '+v.bearingReserved+', entrada '+v.bearingIncoming+', seguridad '+v.bearingSafety+'.</li><li>Tornillos: necesidad '+v.screwNeed+'; físico '+v.screwPhysical+', reservado '+v.screwReserved+', seguridad '+v.screwSafety+'.</li><li>Tapas: necesidad '+v.coverNeed+'; físico '+v.coverPhysical+', reservado '+v.coverReserved+', entrada '+v.coverIncoming+', seguridad '+v.coverSafety+'.</li></ul><button class="btn primary" onclick="alert(\'Asigna al alumno '+String(i+1).padStart(2,"0")+' el código '+String(i+1).padStart(2,"0")+'\')">VER ASIGNACIÓN</button></article>').join("");window.scrollTo({top:0,behavior:"smooth"})}
function openInstructor(){document.getElementById("loginGate").style.display="none";document.getElementById("instructorGate").style.display="grid";document.getElementById("instructorConsole").style.display="none";document.getElementById("instructorUser").focus()}
function closeInstructor(){document.getElementById("instructorGate").style.display="none";document.getElementById("instructorConsole").style.display="none";document.getElementById("loginGate").style.display="grid"}
document.getElementById("instructorLoginForm").addEventListener("submit",e=>{e.preventDefault();const u=document.getElementById("instructorUser").value.trim(),p=document.getElementById("instructorPass").value,box=document.getElementById("instructorError");if(u==="docente"&&p==="NexusU3-2026!"){box.style.display="none";renderInstructorConsole()}else{box.style.display="block";box.textContent="Credenciales incorrectas."}});

function ensureOps(){if(!state.ops)state.ops={continuity:70,budget:70,quality:70,risk:70,events:{},log:[]};if(!state.ops.events)state.ops.events={};if(!state.ops.log)state.ops.log=[]}
function renderLiveOperations(){if(!document.getElementById("liveOperations"))return;ensureOps();const v=getScenario();if(!state.ops.scenarioApplied){liveIncidents[0].description="Producción requiere "+v.demand+" bombas para el "+v.required+". El proveedor habitual "+v.supplier+" estima "+v.normalDays+" días hábiles, pero aún no confirma fecha. La alternativa "+v.altSupplier+" entrega en "+v.altDays+" días con un costo "+v.altPremium+"% mayor.";liveIncidents[1].description="El sistema muestra materiales para "+v.demand+" bombas, pero hay reservas y recepciones pendientes. Rodamientos: físico "+v.bearingPhysical+", reservados "+v.bearingReserved+", entrada "+v.bearingIncoming+", seguridad "+v.bearingSafety+". Producción pide liberar el lote ya.";liveIncidents[2].description="Producción solicita materiales para "+v.demand+" bombas, pero la requisición no incluye todos los campos verificables. La fecha de necesidad es "+v.required+" y el comprador necesita una solicitud cotizable, aprobada y trazable.";state.ops.scenarioApplied=true;}const idx=liveIncidents.findIndex((e,i)=>!state.ops.events[i]);const active=idx<0?null:liveIncidents[idx];$("#activeRoleBadge").textContent="ROL · "+String(state.role||"JEFATURA DE COMPRAS").toUpperCase();if(active){$("#incidentCode").textContent=active.code;$("#incidentTitle").textContent=active.title;$("#incidentDescription").textContent=active.description;$("#incidentActions").innerHTML=active.actions.map((a,j)=>'<button onclick="resolveLiveIncident('+idx+','+j+')">'+a.label+'</button>').join("");$("#incidentFeedback").textContent="";}else{$("#incidentCode").textContent="SIMULACIÓN COMPLETADA";$("#incidentTitle").textContent="Las tres incidencias fueron atendidas";$("#incidentDescription").textContent="Revisa los índices del equipo y comenta con tu grupo qué decisión tomarían diferente y por qué." ;$("#incidentActions").innerHTML='<button onclick="resetLiveIncidents()">↻ Reiniciar centro de incidentes</button>';}
["continuity","budget","quality","risk"].forEach(k=>{const v=Math.max(0,Math.min(100,Number(state.ops[k]??70)));$("#metric"+k[0].toUpperCase()+k.slice(1)).style.width=v+"%";$("#metric"+k[0].toUpperCase()+k.slice(1)+"Text").textContent=v+" / 100";});$("#opsLog").innerHTML=(state.ops.log.length?state.ops.log.slice(-5).reverse().map(x=>'<div class="ops-log-line"><b>['+esc(x.tag)+']</b> '+esc(x.text)+'</div>').join(""):'<div class="ops-log-line"><b>[SYSTEM]</b> Simulación preparada. Esperando primera decisión.</div>')}
function resolveLiveIncident(i,j){ensureOps();if(state.ops.events[i])return;const event=liveIncidents[i],choice=event.actions[j];Object.keys(choice.delta).forEach(k=>state.ops[k]=Math.max(0,Math.min(100,Number(state.ops[k]??70)+choice.delta[k])));let explanation=choice.feedback;if(i===1){const v=getScenario();explanation+="\n\n¿POR QUÉ?\n1. El saldo del sistema es solo una referencia; puede incluir piezas reservadas o bloqueadas.\n2. Almacén debe separar físicamente existente, reservado y pendiente de inspección.\n3. Calcula disponibilidad utilizable = físico − reservas − bloqueos no liberados.\n4. Añade recepciones únicamente si están confirmadas y llegan antes de la fecha de necesidad.\n5. Comunica la cantidad neta con evidencia y libera solo el lote validado.\n\nEn este escenario: "+v.bearingPhysical+" físicos − "+v.bearingReserved+" reservados = "+(v.bearingPhysical-v.bearingReserved)+" libres antes de considerar la recepción de "+v.bearingIncoming+". Revisa también material bloqueado y stock de seguridad antes de comprometer la entrega.";}state.ops.events[i]={choice:j,at:new Date().toISOString(),feedback:explanation};state.ops.log.push({tag:"INC "+String(i+1).padStart(2,"0"),text:choice.label+" → "+explanation});$("#incidentFeedback").textContent=explanation;save();renderLiveOperations();$("#incidentFeedback").textContent=explanation;updateCommandDashboard()}
function resetLiveIncidents(){if(!confirm("¿Reiniciar los tres incidentes y sus indicadores operativos?"))return;state.ops={continuity:70,budget:70,quality:70,risk:70,events:{},log:[],scenarioApplied:false};save();renderLiveOperations()}

function filterMissionNav(query){const q=(query||"").toLowerCase().trim();document.querySelectorAll("#nav [data-mission-index]").forEach(b=>{const i=Number(b.dataset.missionIndex),m=missions[i];b.style.display=!q||m.title.toLowerCase().includes(q)||m.topic.toLowerCase().includes(q)||m.brief.toLowerCase().includes(q)?"":"none"})}
function toggleNexusSidebar(){$(".shell").classList.toggle("sidebar-open")}
document.getElementById("nexusLoginForm").addEventListener("submit",e=>{e.preventDefault();const name=$("#loginFullName").value.trim(),group=$("#loginGroup").value.trim(),code=$("#loginStudentCode")?$("#loginStudentCode").value:"";if(!code){alert("Selecciona el código de alumno que te asignó el docente.");return;}if(name.length<5){alert("Escribe tu nombre completo.");return}$("#fullName").value=name;$("#group").value=group;startMission()});

load();$("#loginFullName").value=state.name||"";$("#loginGroup").value=state.group||"";if($("#loginStudentCode"))$("#loginStudentCode").value=state.studentCode?String(state.studentCode):"";$("#loginSavedName").textContent=state.started?(state.name||"OPERADOR REGISTRADO").toUpperCase():"NUEVO OPERADOR";$("#loginSavedProgress").innerHTML=String(Object.keys(state.passed).filter(k=>state.passed[k]).length).padStart(2,"0")+'<span>/30</span>';$("#loginButtonLabel").textContent=state.started?"RETOMAR MI MISIÓN":"ENTRAR AL CENTRO DE CONTROL";renderNav();updateStatus();updateCommandDashboard();

