function learningMethod(m,i){
 let title="Cómo abordar este reto",formula="",steps="";
 if(i===0){title="Método · Diferencia las funciones";steps="1. Identifica si te preguntan por cálculo de materiales o integración de procesos. 2. Asocia MRP con requerimientos y ERP con procesos conectados. 3. Descarta opciones que prometen autorizaciones automáticas."}
 else if(i===1){title="Método · Inventario utilizable";formula="Disponible antes de demanda = físico − reservado + recepción oportuna";steps="1. Resta lo comprometido. 2. Suma entradas solo si están confirmadas y llegan a tiempo. 3. Luego resta la demanda nueva y considera el stock de seguridad si aplica."}
 else if([7,24,25].includes(i)){title="Método · Explica la fórmula";formula=i===24?"Demanda bruta = cantidad de productos × componentes por producto":i===25?"Requerimiento neto = demanda + stock de seguridad − stock libre − recepción oportuna":"Requerimiento neto = demanda + stock de seguridad − disponible utilizable";steps="1. Escribe los datos con sus unidades. 2. Sustituye cada variable. 3. Respeta los signos y calcula paso a paso. 4. Interpreta el resultado: ¿qué cantidad realmente falta?";}
 else if(i===8||i===27){title="Método · Línea de tiempo";formula="Fecha para liberar la orden = fecha requerida − plazo total";steps="1. Empieza por la fecha en que se necesita el material. 2. Retrocede por aprobación, suministro y transporte. 3. Confirma qué fechas son estimadas y cuáles están comprometidas."}
 else if(i===5||i===6||i===20||i===21||i===22){title="Método · Solicitud verificable";steps="1. Identifica material y especificación. 2. Define cantidad y unidad. 3. Agrega fecha y lugar de entrega. 4. Adjunta justificación y evidencia. 5. Comprueba que otra persona pueda entenderlo sin adivinar."}
 else if(i===14){title="Método · Tablero equilibrado";steps="1. Combina indicadores de servicio, costo, calidad y plazo. 2. Revisa el periodo y la fuente. 3. Pregunta qué decisión permite tomar cada indicador."}
 else if(i===15){title="Método · Roles claros";steps="1. Asigna quién ejecuta. 2. Define quién autoriza. 3. Identifica quién aporta información y quién necesita conocer el resultado. 4. Evita que una tarea crítica quede sin responsable."}
 else if(i===23){title="Método · Prioriza con criterios";formula="Prioridad = impacto operativo + urgencia verificable + criticidad";steps="No es una fórmula universal con ponderaciones fijas: úsala como lista de criterios. Compara casos con los mismos criterios y registra por qué uno debe atenderse primero."}
 else {steps="1. Lee el escenario y la pregunta. 2. Localiza los datos que sí están confirmados. 3. Separa hechos, supuestos y riesgos. 4. Elige la acción que se pueda justificar con evidencia y define qué validarías después."}
 return '<div class="learning-method"><h4>'+title+'</h4>'+(formula?'<div class="method-formula">'+formula+'</div>':"")+'<p>'+steps+'</p><p class="method-note"><b>Comprobación:</b> puedes explicar por qué tu decisión funciona y qué dato podría cambiarla.</p></div>';
}
